  'aiworkspace.demo.quarterly.introTitle': '2026年第2四半期の経営分析',
  'aiworkspace.demo.quarterly.introText': 'これは2026年第2四半期の一般的な売上テーブルで、地域別・製品別の売上高、原価、目標、前四半期の売上高が入っています。データソースモードで数値を直接変更できます。また、キャンバス上のウィッシュブロックに知りたい分析を一文で書き、カードの「分析」「マクロを作成」「マクロを実行」を順に押してください。各ステップは完了するとすぐに結果が書き込まれます。結果に満足できない場合は、前のタブに戻ってやり直すか、元に戻してください。青い破線の矢印はウィッシュが読み取る入力、オレンジの矢印はウィッシュが生成した結果を示します。データを変更したら、もう一度マクロを実行してください。',
