  'aiworkspace.demo.film.howto.title': 'AI ショートフィルムのワークフロー：キャラクター設定 → キャラクター画像 → ストーリーボード → 完成映像',
  'aiworkspace.demo.film.howto.text': '左から右へ進む生成フローですが、各ノードは通常のキャンバスオブジェクトです。左側には、直接編集できる脚本、キャラクター表、スタイルがあります。各段階は1つのウィッシュブロックで、カードの「分析」「マクロを作成」「マクロを実行」を順に押すと、各ステップの完了ごとに結果が書き込まれます。ある段階の結果が次の段階の入力になるため、左から右へ順に実行してください。青い破線の矢印はウィッシュが読み取る入力から、オレンジの矢印はウィッシュが生成した結果へ向かいます。キャラクター表や脚本を変更すると、下流の結果が「古い」と表示されるので、順に再実行してください。画像と動画は Zone の AI モデルが生成します。',
