  'aiworkspace.demo.film.wish1.output': 'キャラクター設定画',
  'aiworkspace.demo.film.wish2.title': 'ウィッシュブロック ②：ストーリーボードを生成',
  'aiworkspace.demo.film.wish2.prompt': '「{{script}}」のシーンに、「{{sheets}}」と「{{style}}」を組み合わせてストーリーボードを生成してください。1シーンにつき1ショットとし、ショットリスト（ショット番号、シーン、ショットサイズ、登場キャラクター、動作、尺）と各ショットの画を出力してください。',
